        "/dim.css": ("text/css; charset=utf-8", #"""
/*! daisyUI 5.7.50 (MIT License, https://github.com/saadeghi/daisyui): the "dim" theme, used when the phone is in dark mode */
:root:has(input.theme-controller[value=dim]:checked),[data-theme="dim"] {
color-scheme: dark;
--color-base-100: oklch(30.857% 0.023 264.149);
--color-base-200: oklch(28.036% 0.019 264.182);
--color-base-300: oklch(26.346% 0.018 262.177);
--color-base-content: oklch(82.901% 0.031 222.959);
--color-primary: oklch(86.133% 0.141 139.549);
--color-primary-content: oklch(17.226% 0.028 139.549);
--color-secondary: oklch(73.375% 0.165 35.353);
--color-secondary-content: oklch(14.675% 0.033 35.353);
--color-accent: oklch(74.229% 0.133 311.379);
--color-accent-content: oklch(14.845% 0.026 311.379);
--color-neutral: oklch(24.731% 0.02 264.094);
--color-neutral-content: oklch(82.901% 0.031 222.959);
--color-info: oklch(86.078% 0.142 206.182);
--color-info-content: oklch(17.215% 0.028 206.182);
--color-success: oklch(86.171% 0.142 166.534);
--color-success-content: oklch(17.234% 0.028 166.534);
--color-warning: oklch(86.163% 0.142 94.818);
--color-warning-content: oklch(17.232% 0.028 94.818);
--color-error: oklch(82.418% 0.099 33.756);
--color-error-content: oklch(16.483% 0.019 33.756);
--radius-selector: 1rem;
--radius-field: 0.5rem;
--radius-box: 1rem;
--size-selector: 0.25rem;
--size-field: 0.25rem;
--border: 1px;
--depth: 0;
--noise: 0;
}

"""#),
        "/": ("text/html; charset=utf-8", #"""
<!doctype html>
<html lang="en" data-theme="nord">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="default">
<meta name="apple-mobile-web-app-title" content="Glide">
<meta name="format-detection" content="telephone=no">
<meta name="color-scheme" content="light dark">
<meta name="theme-color" content="#eceff4" media="(prefers-color-scheme: light)">
<meta name="theme-color" content="#2a303c" media="(prefers-color-scheme: dark)">
<meta name="referrer" content="no-referrer">
<link rel="apple-touch-icon" href="/icon-180.png">
<link rel="icon" type="image/png" href="/icon-180.png">
<title>Glide</title>
<link rel="stylesheet" href="/daisy.css">
<link rel="stylesheet" href="/dim.css">
<link rel="stylesheet" href="/app.css">
<script>
  // Nord when the phone is light, daisyUI "dim" when it is dark; follows the system setting live.
  (function () {
    var m = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
    function apply() { document.documentElement.setAttribute('data-theme', m && m.matches ? 'dim' : 'nord'); }
    apply();
    if (m && m.addEventListener) m.addEventListener('change', apply);
  })();
</script>
</head>
<body>
<div id="app" class="app" aria-live="polite"></div>
<nav id="tabs" class="tabbar" aria-label="Sections" hidden></nav>
<div id="toast" class="toast-box" role="status" aria-live="polite"></div>
<noscript><p class="p-4">Glide Remote needs JavaScript. Turn it on in Settings, then Safari, then Advanced.</p></noscript>
<script src="/crypto.js"></script>
<script src="/api.js"></script>
<script src="/app.js"></script>
</body>
</html>

"""#),
    ]

    static let binary: [String: (type: String, base64: String)] = [
        "/icon-180.png": ("image/png", ""),
    ]

    /// The asset for a request path ("/index.html" is "/"), as bytes. nil when there is none.
    static func asset(_ path: String) -> (type: String, data: Data)? {
        let p = path == "/index.html" ? "/" : path
        if let f = files[p] { return (f.type, Data(f.body.utf8)) }
        if let b = binary[p], let d = Data(base64Encoded: b.base64) { return (b.type, d) }
        return nil
    }
}
